import React from 'react';
import { Link } from 'react-router-dom';

function LandingPage() {
    return (
        <div>
            <h1>Welcome</h1>
            <p>Please choose an option:</p>
            <Link to="/login">Login</Link>
            <br />
            <Link to="/step1">Register</Link>
        </div>
    );
}

export default LandingPage;
